library(ggrepel)
library(patchwork)
library(cowplot)
library(grid)

# Load pre-computed TPR/FPR and model size data (generated by preprocess_tiles.R).
# This runs ONCE at app startup Slider updates only re-apply threshold logic.
load("precomputed_tiles.RData")  # loads: precomp_log03, precomp_log005, precomp_lin

methods <- c("FU", "FSel_AIC", "Step_FSel_AIC", "ABE_AIC", "BE_BIC", "BE_005",
             "BE_AIC", "BE_05", "Lasso", "RLasso", "RLasso_BIC", "AdaLasso")

# core tile-building function (uses pre-computed TPR/FPR & model size)
# methods_subset: optional character vector restricting which methods are shown.
#   When NULL (default) all 8 methods are displayed; pass a subset for narrow plots.
create_tiles <- function(precomp,
                         TPR_mild_group, FPR_mild_group,
                         TPR_medium_group, FPR_medium_group,
                         TPR_strict_group, FPR_strict_group,
                         methods_subset = NULL) {
  
  EPV   <- precomp$EPV
  title <- precomp$title
  # Round EPV values for display labels
  epv_labels <- round(as.numeric(as.character(EPV)))
  
  # Pre-computed data,  o file I/O or heavy computation here
  res_long_TPR_FPR   <- precomp$TPR_FPR       # list("strong"=..., "weak"=...)
  res_long_model_size <- precomp$model_size    # list("strong"=..., "weak"=...)
  
  df <- data.frame(Var2 = character(), crit_fulfilled = character(),
                   L1 = character(), signal = character(), modelsize = numeric())
  
  for (i in 1:2) {
    sig      <- c("strong", "weak")[i]
    tpr_fpr  <- res_long_TPR_FPR[[sig]] %>% rename(noise = pred)
    msize    <- res_long_model_size[[sig]]
    
    for (method in c("BE_05", "Lasso")) {
      df <- rbind(df,
                  tpr_fpr %>% filter(L1 == method) %>%
                    group_by(Var2) %>%
                    summarise(
                      crit_fulfilled = ifelse(
                        all(value[noise == FALSE] >= TPR_mild_group) &
                          all(value[noise == TRUE]  <= FPR_mild_group), "green", "red"),
                      .groups = "drop"
                    ) %>%
                    mutate(L1 = method, signal = sig) %>%
                    left_join(msize, by = c("Var2", "L1"))
      )
    }
    
    for (method in c("BE_AIC", "RLasso", "AdaLasso")) {
      df <- rbind(df,
                  tpr_fpr %>% filter(L1 == method) %>%
                    group_by(Var2) %>%
                    summarise(
                      crit_fulfilled = ifelse(
                        all(value[noise == FALSE] >= TPR_medium_group) &
                          all(value[noise == TRUE] <= FPR_medium_group), "green", "red"),
                      .groups = "drop"
                    ) %>%
                    mutate(L1 = method, signal = sig) %>%
                    left_join(msize, by = c("Var2", "L1"))
      )
    }
    
    for (method in c("BE_BIC", "BE_005", "RLasso_BIC")) {
      df <- rbind(df,
                  tpr_fpr %>% filter(L1 == method) %>%
                    group_by(Var2) %>%
                    summarise(
                      crit_fulfilled = ifelse(
                        all(value[noise == FALSE] >= TPR_strict_group) &
                          all(value[noise == TRUE]  <= FPR_strict_group), "green", "red"),
                      .groups = "drop"
                    ) %>%
                    mutate(L1 = method, signal = sig) %>%
                    left_join(msize, by = c("Var2", "L1"))
      )
    }
  }
  
  df$EPV <- df$Var2
  levels(df$EPV) <- EPV
  
  # Determine which methods to display; filter data accordingly
  method_levels_full <- c("Lasso", "BE_05", "BE_AIC", "AdaLasso", "RLasso",
                          "BE_005", "BE_BIC", "RLasso_BIC")
  method_levels <- if (!is.null(methods_subset)) methods_subset else method_levels_full
  df <- df %>% filter(L1 %in% method_levels)
  method_labels <- c(
    "BE_05"      = "BE(0.50)",
    "Lasso"      = "Lasso(CV)",
    "BE_AIC"     = "BE(AIC)",
    "RLasso"     = "RLasso(CV)",
    "AdaLasso"   = "AdaLasso(CV)",
    "BE_BIC"     = "BE(BIC)",
    "BE_005"     = "BE(0.05)",
    "RLasso_BIC" = "RLasso(BIC)"
  )
  facet_bg_colors <- c(
    "BE_05"      = "#e6f2ff",
    "Lasso"      = "#e6f2ff",
    "BE_AIC"     = "#fff5e6",
    "RLasso"     = "#fff5e6",
    "AdaLasso"   = "#fff5e6",
    "BE_BIC"     = "#f2e6ff",
    "BE_005"     = "#f2e6ff",
    "RLasso_BIC" = "#f2e6ff"
  )
  
  df_plot <- df %>%
    mutate(
      Var2   = factor(Var2, levels = sort(unique(Var2), decreasing = TRUE)),
      signal = factor(signal, levels = c("strong", "weak")),
      L1     = factor(L1, levels = method_levels),
      mark   = case_when(
        crit_fulfilled == "green" ~ "\u2714",
        crit_fulfilled == "red"   ~ "\u2716",
        TRUE ~ ""
      ),
      modelsize_label = paste0("(", round(modelsize, 1), ")")
    )
  
  df_bg <- tibble(
    L1      = factor(method_levels, levels = method_levels),
    xmin    = -Inf,
    xmax    = +Inf,
    ymin    = -Inf,
    ymax    = +Inf,
    bg_fill = facet_bg_colors[method_levels]
  )
  
  method_labels_2line <- setNames(
    paste0(method_labels[method_levels], "\nstrong  |  weak"),
    method_levels
  )
  
  ggplot() +
    geom_rect(data = df_bg,
              aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
              fill = df_bg$bg_fill, color = NA, inherit.aes = FALSE, alpha = 1) +
    geom_tile(data = df_plot,
              aes(x = signal, y = Var2, fill = crit_fulfilled),
              color = "white", width = 0.82, height = 0.92) +
    geom_text(data = df_plot %>% filter(crit_fulfilled == "green"),
              aes(x = signal, y = Var2, label = mark),
              color = "#1a7a1a", size = 3.5, hjust = 0, nudge_x = -0.3,
              vjust = 0.5, nudge_y = 0) +
    geom_text(data = df_plot %>% filter(crit_fulfilled == "red"),
              aes(x = signal, y = Var2, label = mark),
              size = 3.5,
              hjust = 0, nudge_x = -0.3, vjust = 0.5, nudge_y = 0) +
    geom_text(data = df_plot,
              aes(x = signal, y = Var2, label = modelsize_label),
              color = "black", size = 3.0, hjust = 0,
              nudge_x = -0.05, vjust = 0.5, nudge_y = 0) +
    scale_fill_manual(values = c("green" = "#b8eab8", "red" = "#f5b8b8")) +
    facet_wrap(~ L1, ncol = length(method_levels),
               labeller = as_labeller(method_labels_2line)) +
    labs(x = NULL, y = "Sample size", fill = NULL, title = title) +
    scale_y_discrete(expand = expansion(add = 0.5),
                     sec.axis = dup_axis(name = "EPV", labels = rev(epv_labels))) +
    theme_minimal(base_size = 12) +
    theme(
      panel.grid             = element_blank(),
      strip.text             = element_text(face = "bold", size = 11, lineheight = 1.1),
      axis.text.x            = element_blank(),
      axis.text.x.top        = element_blank(),
      axis.ticks.x           = element_blank(),
      axis.ticks.x.top       = element_blank(),
      axis.ticks.length.x    = unit(0, "pt"),
      axis.ticks.length.x.top = unit(0, "pt"),
      axis.title.x           = element_blank(),
      axis.title.x.top       = element_blank(),
      axis.text.y            = element_text(size = 10),
      axis.title.y           = element_text(size = 11),
      aspect.ratio         = NULL,
      plot.title             = element_text(face = "bold", size = 14, margin = margin(t = 6, b = 2)),
      plot.title.position    = "plot",
      panel.spacing.x        = unit(2, "pt"),
      plot.margin            = margin(2, 3, 16, 3),
      legend.position        = "none"
    )
}

# Helper: color facet strip backgrounds per-method using gtable manipulation.
# methods_ord: names of methods in facet order. Defaults to the full 8-method order;
#   pass a subset vector when colouring narrow group plots.
color_strips <- function(p, facet_bg_colors, methods_ord = NULL) {
  if (is.null(methods_ord)) {
    methods_ord <- c("Lasso", "BE_05", "BE_AIC", "AdaLasso", "RLasso",
                     "BE_005", "BE_BIC", "RLasso_BIC")
  }
  g <- ggplotGrob(p)
  strip_names <- g$layout$name[grepl("^strip-t", g$layout$name)]
  for (i in seq_along(strip_names)) {
    col <- facet_bg_colors[methods_ord[i]]
    strip_idx <- which(g$layout$name == strip_names[i])
    g$grobs[[strip_idx]]$grobs[[1]]$children[[1]] <-
      grid::rectGrob(gp = grid::gpar(fill = col, col = NA))
  }
  g
}

create_tile_plot <- function(TPR_mild_group, FPR_mild_group,
                             TPR_medium_group, FPR_medium_group,
                             TPR_strict_group, FPR_strict_group,
                             ann_text_size = 4.2,
                             ann_rel_height = 3.2,
                             corr_setting = "nhanes") {
  
  # Select precomp objects based on correlation setting
  if (corr_setting == "nhanes") {
    pc_log03  <- precomp_nhanes_log03
    pc_log005 <- precomp_nhanes_log005
    pc_lin    <- precomp_nhanes_lin
  } else {
    pc_log03  <- precomp_nocorr_log03
    pc_log005 <- precomp_nocorr_log005
    pc_lin    <- precomp_nocorr_lin
  }
  
  plot_log03 <- create_tiles(pc_log03,
                             TPR_mild_group, FPR_mild_group,
                             TPR_medium_group, FPR_medium_group,
                             TPR_strict_group, FPR_strict_group)
  
  plot_log005 <- create_tiles(pc_log005,
                              TPR_mild_group, FPR_mild_group,
                              TPR_medium_group, FPR_medium_group,
                              TPR_strict_group, FPR_strict_group)
  
  plot_lin <- create_tiles(pc_lin,
                           TPR_mild_group, FPR_mild_group,
                           TPR_medium_group, FPR_medium_group,
                           TPR_strict_group, FPR_strict_group)
  
  tile_bg_colors <- c(
    "Lasso" = "#e6f2ff", "BE_05" = "#e6f2ff",
    "BE_AIC" = "#fff5e6", "AdaLasso" = "#fff5e6", "RLasso" = "#fff5e6",
    "BE_005" = "#f2e6ff", "BE_BIC" = "#f2e6ff", "RLasso_BIC" = "#f2e6ff"
  )
  g_log03  <- color_strips(plot_log03,  tile_bg_colors)
  g_log005 <- color_strips(plot_log005, tile_bg_colors)
  g_lin    <- color_strips(plot_lin,    tile_bg_colors)
  
  # per-group threshold labels
  # Build an annotation row that reuses the same facet_wrap(~ L1, ncol=8)
  # structure as the tile plots, so columns are guaranteed to align.
  # Each facet shows a single coloured label; the middle facet of each group
  # carries the threshold text, the others are blank.
  method_levels_ann <- c("Lasso", "BE_05", "BE_AIC", "AdaLasso", "RLasso",
                         "BE_005", "BE_BIC", "RLasso_BIC")
  
  group1_label <- paste0("MILD SELECTION\nTPR\u2265", TPR_mild_group,
                         "\nFPR\u2264", FPR_mild_group)
  group2_label <- paste0("BALANCED SELECTION\nTPR\u2265", TPR_medium_group,
                         "\nFPR\u2264", FPR_medium_group)
  group3_label <- paste0("STRICT SELECTION\nTPR\u2265", TPR_strict_group,
                         "\nFPR\u2264", FPR_strict_group)
  
  # Label placement: one label per group, in the middle (or left-of-middle) facet.
  # Group 1: 2 facets (Lasso, BE_05) - label in Lasso only, slightly right-of-center
  #          using x = 2.0 so it visually centers across both columns.
  # Group 2: 3 facets (BE_AIC, AdaLasso, RLasso) - label in middle (AdaLasso).
  # Group 3: 3 facets (BE_005, BE_BIC, RLasso_BIC) - label in middle (BE_BIC).
  ann_text <- c(
    Lasso      = group1_label,
    BE_05      = "",
    BE_AIC     = "",
    AdaLasso   = group2_label,
    RLasso     = "",
    BE_005     = "",
    BE_BIC     = group3_label,
    RLasso_BIC = ""
  )
  ann_x <- c(
    Lasso = 2.0,   # right-of-center in Lasso facet to visually span into BE_05
    BE_05 = 1.5, BE_AIC = 1.5, AdaLasso = 1.5, RLasso = 1.5,
    BE_005 = 1.5, BE_BIC = 1.5, RLasso_BIC = 1.5
  )
  ann_bg <- c(
    Lasso = "#e6f2ff", BE_05 = "#e6f2ff",
    BE_AIC = "#fff5e6", AdaLasso = "#fff5e6", RLasso = "#fff5e6",
    BE_005 = "#f2e6ff", BE_BIC = "#f2e6ff", RLasso_BIC = "#f2e6ff"
  )
  
  # Annotation row: single continuous-axis ggplot, no facets
  # Columns 1-8 map to: Lasso, BE_05, BE_AIC, AdaLasso, RLasso, BE_005, BE_BIC, RLasso_BIC
  # Group spans: mild=1-2, intermediate=3-5, strict=6-8
  # Background rects and text are all in one coordinate system - no facet clipping.
  ann_rects <- data.frame(
    xmin = c(0.5, 2.5, 5.5),
    xmax = c(2.5, 5.5, 8.5),
    bg   = c("#e6f2ff", "#fff5e6", "#f2e6ff")
  )
  ann_labels <- data.frame(
    x     = c(1.5, 4.0, 7.0),   # center of each group span
    label = c(group1_label, group2_label, group3_label)
  )
  
  ann_plot <- ggplot() +
    geom_rect(data = ann_rects,
              aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf, fill = bg),
              color = NA, inherit.aes = FALSE) +
    scale_fill_identity() +
    geom_text(data = ann_labels,
              aes(x = x, y = 0.5, label = label),
              hjust = 0.5, vjust = 0.5, size = ann_text_size,
              lineheight = 1.2, fontface = "bold", color = "black") +
    scale_x_continuous(limits = c(0.5, 8.5), expand = c(0, 0)) +
    scale_y_continuous(limits = c(0, 1), expand = c(0, 0),
                       sec.axis = dup_axis(name = "EPV", labels = NULL,
                                           breaks = NULL)) +
    labs(x = NULL, y = "Sample size", fill = NULL) +
    theme_minimal(base_size = 12) +
    theme(
      panel.grid         = element_blank(),
      axis.text          = element_blank(),
      axis.ticks         = element_blank(),
      axis.ticks.length  = unit(0, "pt"),
      axis.title.y       = element_text(size = 11, color = "transparent"),
      plot.margin        = margin(3, 3, 3, 3),
      legend.position    = "none"
    )
  
  # cowplot handles gtables natively - no wrap_elements needed.
  # Use rel_heights proportional to row counts so plots scale with available space.
  # log03=8 rows, log005=4 rows, lin=8 rows, annotation=small fixed fraction.
  cowplot::plot_grid(
    g_lin, g_log03, g_log005, ann_plot,
    ncol = 1,
    rel_heights = c(8 + 2.0, 8 + 2.0, 4 + 3.5, ann_rel_height),
    align = "v",
    axis  = "lr"
  )
}

#  Build a narrow single-scenario - single-group plot (win_width < 900)
# One precomp (scenario) - one group: used in the 9-panel narrow layout where
# plots are ordered by regression type first, then mild / balanced / strict.
# precomp: one of precomp_log03, precomp_log005, precomp_lin
# group:   one of "mild", "balanced", "strict"
create_tile_single <- function(precomp, group,
                               TPR_mild_group, FPR_mild_group,
                               TPR_medium_group, FPR_medium_group,
                               TPR_strict_group, FPR_strict_group,
                               ann_text_size = 4.2,
                               ann_rel_height = 3.2,
                               corr_setting = "nhanes") {
  
  methods_map <- list(
    mild     = c("Lasso", "BE_05"),
    balanced = c("BE_AIC", "AdaLasso", "RLasso"),
    strict   = c("BE_005", "BE_BIC", "RLasso_BIC")
  )
  group_colors <- c(mild = "#e6f2ff", balanced = "#fff5e6", strict = "#f2e6ff")
  group_labels <- list(
    mild     = paste0("MILD SELECTION\nTPR\u2265", TPR_mild_group,
                      "\nFPR\u2264", FPR_mild_group),
    balanced = paste0("BALANCED SELECTION\nTPR\u2265", TPR_medium_group,
                      "\nFPR\u2264", FPR_medium_group),
    strict   = paste0("STRICT SELECTION\nTPR\u2265", TPR_strict_group,
                      "\nFPR\u2264", FPR_strict_group)
  )
  
  msub <- methods_map[[group]]
  gcol <- group_colors[group]
  glbl <- group_labels[[group]]
  nm   <- length(msub)
  
  tile_bg_colors <- c(
    "Lasso" = "#e6f2ff", "BE_05" = "#e6f2ff",
    "BE_AIC" = "#fff5e6", "AdaLasso" = "#fff5e6", "RLasso" = "#fff5e6",
    "BE_005" = "#f2e6ff", "BE_BIC" = "#f2e6ff", "RLasso_BIC" = "#f2e6ff"
  )
  
  # Build tile plot for this one scenario, subset to this group's methods
  p <- create_tiles(precomp,
                    TPR_mild_group, FPR_mild_group,
                    TPR_medium_group, FPR_medium_group,
                    TPR_strict_group, FPR_strict_group,
                    methods_subset = msub)
  g <- color_strips(p, tile_bg_colors, msub)
  
  # Annotation row spanning this group's methods
  ann_rects  <- data.frame(xmin = 0.5, xmax = nm + 0.5, bg = gcol)
  ann_labels <- data.frame(x = (nm + 1) / 2, label = glbl)
  
  ann_plot <- ggplot() +
    geom_rect(data = ann_rects,
              aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf, fill = bg),
              color = NA, inherit.aes = FALSE) +
    scale_fill_identity() +
    geom_text(data = ann_labels,
              aes(x = x, y = 0.5, label = label),
              hjust = 0.5, vjust = 0.5, size = ann_text_size,
              lineheight = 1.2, fontface = "bold", color = "black") +
    scale_x_continuous(limits = c(0.5, nm + 0.5), expand = c(0, 0)) +
    scale_y_continuous(limits = c(0, 1), expand = c(0, 0),
                       sec.axis = dup_axis(name = "EPV", labels = NULL,
                                           breaks = NULL)) +
    labs(x = NULL, y = "Sample size", fill = NULL) +
    theme_minimal(base_size = 12) +
    theme(
      panel.grid         = element_blank(),
      axis.text          = element_blank(),
      axis.ticks         = element_blank(),
      axis.ticks.length  = unit(0, "pt"),
      axis.title.y       = element_text(size = 11, color = "transparent"),
      plot.margin        = margin(3, 3, 3, 3),
      legend.position    = "none"
    )
  
  # rel_heights: tile area (8 units) + annotation.
  # Actual pixel height is controlled by CSS (proportional to scenario row count).
  cowplot::plot_grid(
    g, ann_plot,
    ncol        = 1,
    rel_heights = c(8, ann_rel_height),
    align       = "v",
    axis        = "lr"
  )
}

