#####################################################################################
# SHINY SERVER
#####################################################################################

server <- function(input, output, session) {
  
  
  # Shared helper: annotation scaling based on window height
  get_ann_params <- function() {
    h <- if (!is.null(input$win_height) && input$win_height > 0)
      input$win_height else 900
    list(
      ann_size       = max(2.5, min(5.5, round(4.2 * h / 900, 2))),
      ann_rel_height = max(2.0, min(4.5, round(3.2 * h / 900, 2)))
    )
  }
  
  # Null-safe accessor: returns "nhanes" if input$corr_setting is NULL (on startup)
  get_corr_setting <- function() {
    if (is.null(input$corr_setting) || length(input$corr_setting) == 0)
      "nhanes"
    else
      input$corr_setting
  }
  
  # Wide plot (win_width >= 900) - all 8 methods, all 3 scenarios
  tile_plot <- eventReactive(list(input$update, input$corr_setting), {
    withProgress(message = "Building tile plot...", value = 0.1, {
      ap <- get_ann_params()
      p <- create_tile_plot(
        TPR_mild_group   = input$TPR_mild,
        FPR_mild_group   = input$FPR_mild,
        TPR_medium_group = input$TPR_medium,
        FPR_medium_group = input$FPR_medium,
        TPR_strict_group = input$TPR_strict,
        FPR_strict_group = input$FPR_strict,
        ann_text_size    = ap$ann_size,
        ann_rel_height   = ap$ann_rel_height,
        corr_setting     = get_corr_setting()
      )
      incProgress(0.9)
      p
    })
  }, ignoreNULL = FALSE)
  
  output$tilePlot <- renderPlot({
    req(tile_plot())
    tile_plot()
  },
  res = 80,
  height = function() {
    h <- session$clientData$output_tilePlot_height
    if (is.null(h) || !is.numeric(h) || h < 10) {
      wh <- if (!is.null(input$win_height) && input$win_height > 0) input$win_height else 900
      max(500, wh)
    } else {
      max(500, as.integer(h))
    }
  })
  
  # Narrow plots (win_width < 900) - 9 panels: scenario first, then group
  # Factory: creates an eventReactive for one scenario - group combination.
  # precomp objects are resolved once at factory-call time and captured in the
  # closure; R lexical scoping guarantees each closure holds its own values.
  make_single_plot <- function(scenario, group) {
    precomp_map_nhanes <- list(log03 = precomp_nhanes_log03,
                               log005 = precomp_nhanes_log005,
                               lin   = precomp_nhanes_lin)
    precomp_map_nocorr <- list(log03 = precomp_nocorr_log03,
                               log005 = precomp_nocorr_log005,
                               lin   = precomp_nocorr_lin)
    eventReactive(list(input$update, input$corr_setting), {
      pc <- if (get_corr_setting() == "none")
        precomp_map_nocorr[[scenario]]
      else
        precomp_map_nhanes[[scenario]]
      withProgress(message = paste0("Building ", scenario, "/", group, "\u2026"),
                   value = 0.1, {
                     ap <- get_ann_params()
                     p <- create_tile_single(
                       precomp          = pc,
                       group            = group,
                       TPR_mild_group   = input$TPR_mild,
                       FPR_mild_group   = input$FPR_mild,
                       TPR_medium_group = input$TPR_medium,
                       FPR_medium_group = input$FPR_medium,
                       TPR_strict_group = input$TPR_strict,
                       FPR_strict_group = input$FPR_strict,
                       ann_text_size    = ap$ann_size,
                       ann_rel_height   = ap$ann_rel_height,
                       corr_setting     = input$corr_setting
                     )
                     incProgress(0.9)
                     p
                   })
    }, ignoreNULL = FALSE)
  }
  
  # Height helper: falls back to proportional win_height when output is hidden.
  # log005 has 4 EPV rows (~28% of height); log03 and lin have 8 rows (~38%).
  single_height <- function(output_id, scenario) {
    function() {
      h <- session$clientData[[paste0("output_", output_id, "_height")]]
      if (is.null(h) || !is.numeric(h) || h < 10) {
        wh <- if (!is.null(input$win_height) && input$win_height > 0)
          input$win_height else 900
        frac <- if (scenario == "log005") 0.28 else 0.38
        max(200, round(wh * frac))
      } else {
        max(200, as.integer(h))
      }
    }
  }
  
  # Create all 9 reactives (scenario-first order)
  tp_lin_mild       <- make_single_plot("lin",    "mild")
  tp_lin_balanced   <- make_single_plot("lin",    "balanced")
  tp_lin_strict     <- make_single_plot("lin",    "strict")
  tp_log03_mild     <- make_single_plot("log03",  "mild")
  tp_log03_balanced <- make_single_plot("log03",  "balanced")
  tp_log03_strict   <- make_single_plot("log03",  "strict")
  tp_log005_mild    <- make_single_plot("log005", "mild")
  tp_log005_balanced <- make_single_plot("log005", "balanced")
  tp_log005_strict  <- make_single_plot("log005", "strict")
  
  # Register all 9 renderPlot outputs
  output$tilePlot_log03_mild <- renderPlot({
    req(tp_log03_mild()); tp_log03_mild()
  }, res = 80, height = single_height("tilePlot_log03_mild", "log03"))
  
  output$tilePlot_log03_balanced <- renderPlot({
    req(tp_log03_balanced()); tp_log03_balanced()
  }, res = 80, height = single_height("tilePlot_log03_balanced", "log03"))
  
  output$tilePlot_log03_strict <- renderPlot({
    req(tp_log03_strict()); tp_log03_strict()
  }, res = 80, height = single_height("tilePlot_log03_strict", "log03"))
  
  output$tilePlot_log005_mild <- renderPlot({
    req(tp_log005_mild()); tp_log005_mild()
  }, res = 80, height = single_height("tilePlot_log005_mild", "log005"))
  
  output$tilePlot_log005_balanced <- renderPlot({
    req(tp_log005_balanced()); tp_log005_balanced()
  }, res = 80, height = single_height("tilePlot_log005_balanced", "log005"))
  
  output$tilePlot_log005_strict <- renderPlot({
    req(tp_log005_strict()); tp_log005_strict()
  }, res = 80, height = single_height("tilePlot_log005_strict", "log005"))
  
  output$tilePlot_lin_mild <- renderPlot({
    req(tp_lin_mild()); tp_lin_mild()
  }, res = 80, height = single_height("tilePlot_lin_mild", "lin"))
  
  output$tilePlot_lin_balanced <- renderPlot({
    req(tp_lin_balanced()); tp_lin_balanced()
  }, res = 80, height = single_height("tilePlot_lin_balanced", "lin"))
  
  output$tilePlot_lin_strict <- renderPlot({
    req(tp_lin_strict()); tp_lin_strict()
  }, res = 80, height = single_height("tilePlot_lin_strict", "lin"))
  
}

